fn circle(a:V,b:V,c:V,r:f64)->Option<f64>{let d=[b[0]-a[0],b[1]-a[1]];let f=[a[0]-c[0],a[1]-c[1]];let v=f[0]*f[0]+f[1]*f[1]-r*r;if v<=0.0{return Some(0.0);}let aa=d[0]*d[0]+d[1]*d[1];if aa<=1e-12{return None;}let bb=2.0*(f[0]*d[0]+f[1]*d[1]);let q=bb*bb-4.0*aa*v;if q<0.0{return None;}let t=(-bb-q.sqrt())/(2.0*aa);if t>=0.0&&t<=1.0{Some(t)}else{None}}
fn rotate(v:V,a:f64)->V{let c=a.cos();let s=a.sin();[v[0]*c-v[1]*s,v[0]*s+v[1]*c]}
fn local(v:V,s:&Ship)->V{rotate([v[0]-s.position[0],v[1]-s.position[1]],-s.facing)}
fn contains(v:V,p:&[V])->bool{if p.len()<3{return false;}let mut inside=false;let mut j=p.len()-1;for i in 0..p.len(){let a=p[i];let b=p[j];if (a[1]>v[1])!=(b[1]>v[1])&&v[0]<(b[0]-a[0])*(v[1]-a[1])/(b[1]-a[1])+a[0]{inside=!inside;}j=i;}inside}
fn polygon(a:V,b:V,p:&[V])->Option<f64>{if contains(a,p){return Some(0.0);}let d=[b[0]-a[0],b[1]-a[1]];let mut best=1.0;let mut found=false;for i in 0..p.len(){let x=p[(i+p.len()-1)%p.len()];let y=p[i];let e=[y[0]-x[0],y[1]-x[1]];let denom=d[0]*e[1]-d[1]*e[0];if denom.abs()<1e-8{continue;}let r=[a[0]-x[0],a[1]-x[1]];let t=(e[0]*r[1]-e[1]*r[0])/denom;let u=(d[0]*r[1]-d[1]*r[0])/denom;if t>=0.0&&t<=1.0&&u>=0.0&&u<=1.0&&t<=best{best=t;found=true;}}if found{Some(best)}else if contains(b,p){Some(1.0)}else{None}}
